B.WG=s([B.NH],t.J)
B.Nb=new A.cK("Barista",B.WG)
B.Ww=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.My=new A.cq("Try to remember","intro_cannot_remember_name",!0,!1)
B.V5=s([B.My],t.u)
